    age_gate: string;
    description: string;
    /**
     * Icon paths on this node (see [`Room`]).
     */
    icon?: string | null;
    icon_animated: boolean;
    icon_blob_id?: string | null;
    icon_still?: string | null;
    id: string;
    member_count: number;
